  (x.w?(x.ws||WG):LOTS).forEach(function(k){var p=lp(x,k);if(p==null)return;h+='<div class="ltw"><button class="lt" data-add="'+i+'|'+k+'" aria-label="Ajouter '+esc(x.n)+', '+lab(k,x)+'"><b>'+(x.w?String(k).replace(".",",")+" g":k===1?"Unité":"Lot de "+k)+'</b><small'+(p==null?' class="na">à confirmer':'>'+fmt(p))+'</small>'+(p!=null&&k>1&&!x.w?'<span class="pu">'+fmt(p/k)+' / pièce</span>':'')+'</button><div class="stp" hidden><button data-m="'+i+'|'+k+'" data-d="-1" aria-label="Retirer un : '+esc(x.n)+', '+lab(k,x)+'">−</button><span data-q="'+i+'|'+k+'">0</span><button data-m="'+i+'|'+k+'" data-d="1" aria-label="Ajouter un : '+esc(x.n)+', '+lab(k,x)+'">+</button></div></div>'});
